const{Redis:Redis}=require("@upstash/redis"),redis=Redis.fromEnv({automaticDeserialization:!1}),MAX_VALUE_BYTES=2097152;function isValidCode(e){return"string"==typeof e&&/^[a-z0-9-]{1,64}$/.test(e)}function isValidKey(e){return"string"==typeof e&&/^[a-zA-Z0-9_-]{1,64}$/.test(e)}module.exports=async function(e,t){t.setHeader("Cache-Control","no-store");const{code:o,key:s}=e.query;if(!isValidCode(o)||!isValidKey(s))return void t.status(400).json({error:"Invalid or missing code/key"});const r=`household:${o}:${s}`,a=`household:${o}:__meta`;try{if("GET"===e.method){const e=await redis.get(r);return void t.status(200).json({value:null==e?null:e})}if("POST"===e.method){let o=e.body;if("string"==typeof o)try{o=JSON.parse(o)}catch(e){o={}}const i=o&&o.value;if("string"!=typeof i)return void t.status(400).json({error:"value must be a JSON string"});if(i.length>2097152)return void t.status(413).json({error:"value too large"});await redis.set(r,i);const n=Date.now();return await redis.set(a,JSON.stringify({updatedAt:n,changedKey:s})),void t.status(200).json({ok:!0,updatedAt:n})}if("DELETE"===e.method){await redis.del(r);const e=Date.now();return await redis.set(a,JSON.stringify({updatedAt:e,changedKey:s})),void t.status(200).json({ok:!0,updatedAt:e})}t.setHeader("Allow",["GET","POST","DELETE"]),t.status(405).json({error:`Method ${e.method} not allowed`})}catch(e){console.error("household api error",e),t.status(500).json({error:"Storage backend error — is a Redis database connected to this Vercel project?"})}};